package com.aicharacter.v3;
/** Lightweight creature ecology; no beliefs, thoughts, personality or human cognition. */
public final class CreatureLifeEngine {private CreatureLifeEngine(){}
 public static void advance(WorldState s,double minutes,long now){CreatureState c=s.reedling;if(c==null||s.world==null)return;c.hunger=Math.min(1,c.hunger+minutes*.0015);WorldObject o=s.world.object(c.objectId);if(o==null)return;WorldArea a=s.world.area(o.areaId);double risk="RAIN".equals(s.environment.weather)?s.environment.weatherIntensity:0;if(c.hunger>.65){c.activity="forage";c.energy=Math.max(0,c.energy-minutes*.002);}else if(risk>.65||c.energy<.25){c.activity="rest";c.energy=Math.min(1,c.energy+minutes*.003);}else{c.activity="wander";c.energy=Math.max(0,c.energy-minutes*.001);float span=Math.max(20,a.right-a.left-80);double phase=((now/60000L)+(c.id.hashCode()&31))*.17;c.x=(float)(a.left+40+(Math.sin(phase)*.5+.5)*span);}c.areaId=a.id;c.lastUpdate=now;}
 public static boolean perceivable(WorldState s){WorldObject o=s.world==null?null:s.world.object(s.reedling.objectId);if(o==null)return false;WorldArea ga=s.world.areaAt(s.haruX);if(ga==null||!ga.id.equals(s.reedling.areaId))return false;return Math.abs(s.haruX-s.reedling.x)<=160*s.visibility;}
 public static MemoryEntry encounter(WorldState s,long now){if(!perceivable(s))return null;s.reedling.meetHaru(true,now);int k=s.knowledge.getOrDefault("reedling",0);s.knowledge.put("reedling",Math.min(4,k+1));return CognitionEngine.process(s,new Experience("creature_encounter","noticed a small creature nearby",.08,.45).id("creature_"+s.reedling.id+"_"+now).at(s.reedling.areaId,s.reedling.objectId).tag("observe").tag("creature"));}
}
